// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Typed errors, exit codes, what-why-fix messages
// Flo: error set > map error to exit code 0-4 > map error to 3-line message
// I/O: anyerror (caller) > u8 exit code + Mesg (stderr text)
// ===================================================================
const std = @import("std"); const logz = @import("lo-logz-line.zig");
const CF = .{ .okay = 0, .fail = 1, .usag = 2, .drif = 3, .bloc = 4 };
pub const Erro = error{ BadUsage, BadConfig, Drift, Blocked, Fail, NeedVendor, OverCap, KillOn, BadUrl, BlockedHost, NotText, TooBig, RedirectLoop, TooManyRedirects, Timeout, CharUnsupported, HashMismatch, NoKey, NotConfigured, CloudHttp, CloudSql, CloudDeny, DiskFull, AlertFail, NoBrowser, BrowFail, LoginWall, DayCap, BadSpec, StaleSpec, PinBypass, Locked };
pub const Mesg = struct { what: []const u8, whyz: []const u8, fixz: []const u8 };
pub fn usag(what: []const u8, toke: []const u8) error{BadUsage} { logz.logz("args", .erro, what, toke, "run: sc-scra help"); return error.BadUsage; }
pub fn exitCode(erro: anyerror) u8 { return switch (erro) { error.BadUsage, error.BadConfig, error.BadUrl, error.BlockedHost => CF.usag, error.Drift => CF.drif, error.Blocked, error.Locked => CF.bloc, else => CF.fail }; }
pub fn mesg(erro: anyerror) Mesg { return switch (erro) { error.BadUsage => .{ .what = "bad usage", .whyz = "unknown command or flag", .fixz = "run: sc-scra help" }, error.BadConfig => .{ .what = "bad config", .whyz = "aa-conf-main.json has a bad or unknown value", .fixz = "fix the key named above or delete the file for defaults" }, error.Drift => .{ .what = "drift", .whyz = "page shape changed from the saved fixture", .fixz = "review the parser, update the fixture" }, error.Blocked => .{ .what = "blocked", .whyz = "the host served a block page", .fixz = "climb a tier or wait; never retry the same vendor" }, error.NeedVendor => .{ .what = "needs vendor", .whyz = "own GET failed (TLS or block)", .fixz = "let the tier ladder pick a vendor" }, error.OverCap => .{ .what = "spend cap hit", .whyz = "capz_usdz_mont or a vendor credit cap is used up", .fixz = "raise the cap in aa-conf-main.json, then run with go" }, error.KillOn => .{ .what = "kill switch on", .whyz = "all spend is halted", .fixz = "run: sc-scra kill --off" }, error.BadUrl => .{ .what = "bad url", .whyz = "not a plain http(s) URL (userinfo, odd scheme, too long)", .fixz = "pass a full http:// or https:// URL" }, error.BlockedHost => .{ .what = "host refused", .whyz = "private, loopback, link-local or metadata address", .fixz = "only public hosts are fetched" }, error.NotText => .{ .what = "not text", .whyz = "content type is image, video, font or binary", .fixz = "scra stores text only (HTML, JSON, XML)" }, error.TooBig => .{ .what = "body too big", .whyz = "over fetc_body_maxz (also stops gzip bombs)", .fixz = "raise fetc_body_maxz or skip the page" }, error.RedirectLoop => .{ .what = "redirect loop", .whyz = "a redirect points back to a visited URL", .fixz = "skip this URL" }, error.TooManyRedirects => .{ .what = "too many redirects", .whyz = "more hops than fetc_redi_maxz", .fixz = "raise fetc_redi_maxz or skip" }, error.Timeout => .{ .what = "timeout", .whyz = "no answer within fetc_time_seco", .fixz = "retry later or raise fetc_time_seco" }, error.CharUnsupported => .{ .what = "charset unsupported", .whyz = "page is not UTF-8, Latin-1 or UTF-16", .fixz = "skip or use a vendor tier" }, error.NotConfigured => .{ .what = "cloud not configured", .whyz = "no object store + SQL vendor has host, bucket and key file", .fixz = "set clou_endp in aa-conf-main.json and put keys in ~/.zz-base-home-secr/as-apps/ws-webs/sc-scra/<vendor>.key" }, error.CloudHttp => .{ .what = "cloud storage error", .whyz = "the object store refused or timed out", .fixz = "run sync again later; data is safe in the local queue" }, error.CloudSql => .{ .what = "cloud database error", .whyz = "the cloud SQL refused or timed out", .fixz = "run sync again later; data is safe in the local queue" }, error.CloudDeny => .{ .what = "cloud vendor refused", .whyz = "the vendor answered 401, 402 or 403: key rejected, plan full or account suspended", .fixz = "check the key and the free-plan usage; scra skips that vendor until next month and uses the next one" }, error.DiskFull => .{ .what = "local disk cap reached", .whyz = "the data folder is at 95% of capz_disk_gbyt and nothing verified can be pruned", .fixz = "fix the cloud sync (sc-scra sync --live) so old files can be pruned, or raise capz_disk_gbyt" }, error.AlertFail => .{ .what = "alert not delivered", .whyz = "no alert channel answered", .fixz = "set healthchecks.url / resend.key and aler_mail_* in config" }, error.NoKey => .{ .what = "no vendor key", .whyz = "key file missing or empty", .fixz = "put the key on line 1 of ~/.zz-base-home-secr/as-apps/ws-webs/sc-scra/<vendor>.key" }, error.HashMismatch => .{ .what = "stored file damaged", .whyz = "file content does not match its hash", .fixz = "refetch the page" }, error.BadSpec => .{ .what = "bad request spec", .whyz = "file is not a HAR or curl command, or a {param} has no --param", .fixz = "export a fresh HAR or Copy as cURL; pass --param name=value" }, error.StaleSpec => .{ .what = "spec rejected (401/403)", .whyz = "signature, token or cookie in the capture expired", .fixz = "capture a fresh request from your own device" }, error.PinBypass => .{ .what = "spec needs a TLS bypass", .whyz = "capture uses insecure or pinned-key flags", .fixz = "scra never bypasses certificate checks; capture without them" }, error.NoBrowser => .{ .what = "no local browser", .whyz = "Chrome or Edge not found, or brow_enab is false", .fixz = "install Chrome, set brow_path_exec, brow_enab true" }, error.BrowFail => .{ .what = "browser run failed", .whyz = "page action or render failed or timed out", .fixz = "check the steps file and brow_time_seco" }, error.LoginWall => .{ .what = "login wall", .whyz = "session expired or the site asks to log in", .fixz = "run: sc-scra login <name>" }, error.DayCap => .{ .what = "account day cap reached", .whyz = "acct_page_maxz pages used today for this account", .fixz = "wait for tomorrow or raise acct_page_maxz" }, error.Locked => .{ .what = "another run is active", .whyz = "scra.lock in the data folder is held by a live process", .fixz = "wait for that run to end, or stop it, then run again" }, else => .{ .what = "failed", .whyz = @errorName(erro), .fixz = "re-run with --json and check status" } }; }
